}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size - 2; i++) {
            if (buf[i] == 0x1F && buf[i + 1] == 0xBC && buf[i + 2] == 0x00) {
                dctx->frame_start = 1;
                dctx->frame_start_found = 1;
                dctx->frame_offset = i;
                break;
            }
        }
        if (!dctx->frame_start_found)
            return END_NOT_FOUND;
    }

    if (dctx->frame_start_found) {
        int offset = dctx->frame_offset;
        if (offset + 4 > buf_size)
            return END_NOT_FOUND;

        int width = ((buf[offset + 3] << 24) >> 16) | ((buf[offset + 2] << 24) >> 24);
        int height = ((buf[offset + 1] << 24) >> 16) | ((buf[offset] << 24) >> 24);

        int frame_size = dnxhd_get_frame_size(width, height);
        if (frame_size < 0)
            return END_NOT_FOUND;

        int remaining = frame_size - offset;
        if (remaining <= 0) {
            dctx->frame_start_found = 0;
            return remaining;
        } else if (remaining > buf_size) {
            return END_NOT_FOUND;
        } else {
            dctx->frame_start_found = 0;
            return remaining;
        }
    }

    return END_NOT_FOUND;
}

