int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    if (!dctx->frame_start_found) {
        for (int i = 0; i < buf_size; i++) {
            if (buf[i] == 0x00 && i + 1 < buf_size && buf[i + 1] == 0x00 && i + 2 < buf_size && buf[i + 2] == 0x01) {
                dctx->frame_start = i;
                dctx->frame_start_found = 1;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int header_size = dctx->frame_start + 4;
        if (buf_size >= header_size) {
            int width = ((buf[header_size] & 0x3F) << 4) | ((buf[header_size + 1] >> 4) & 0x0F);
            int height = ((buf[header_size + 1] & 0x0F) << 8) | buf[header_size + 2];
            int cid = (buf[header_size + 3] & 0xF0) >> 4;

            int frame_size;
            if (cid == 0) {
                frame_size = width * height * 2;
            } else {
                frame_size = width * height * 4;
            }

            int remaining = frame_size - (dctx->frame_bytes_read + buf_size);
            if (remaining <= 0) {
                dctx->frame_start_found = 0;
                dctx->frame_bytes_read = 0;
                return -remaining;
            } else {
                dctx->frame_bytes_read += buf_size;
                return remaining;
            }
        }
    }

    return END_NOT_FOUND;
}
